@@ -15,6 +15,8 @@
 package s2

 import (
+	"fmt"
+	"io"
 	"math"
 	"slices"
 	"sort"
@@ -1540,3 +1542,294 @@ func maxLevelForEdge(edge Edge) int {
 func (s *ShapeIndex) removeShapeInternal(removed *removedShape, allEdges [][]faceEdge, t *tracker) {
 	// TODO(roberts): finish the implementation of this.
 }
+
+const (
+	maxEncodedShapes        = 10000000
+	maxEncodedCells         = 10000000
+	maxClippedShapesPerCell = 10000000
+	maxEdgesPerClippedShape = 10000000
+)
+
+// Encode encodes the ShapeIndex into w.
+func (s *ShapeIndex) Encode(w io.Writer) error {
+	s.maybeApplyUpdates()
+
+	s.mu.RLock()
+	defer s.mu.RUnlock()
+
+	e := &encoder{w: w}
+	s.encode(e)
+	return e.err
+}
+
+func (s *ShapeIndex) encode(e *encoder) {
+	e.writeInt8(encodingVersion)
+	e.writeUvarint(uint64(s.maxEdgesPerCell))
+	e.writeUvarint(uint64(s.nextID))
+
+	// Write shapes map
+	e.writeUvarint(uint64(len(s.shapes)))
+	// Sort shapeIDs for deterministic encoding
+	shapeIDs := make([]int32, 0, len(s.shapes))
+	for id := range s.shapes {
+		shapeIDs = append(shapeIDs, id)
+	}
+	slices.Sort(shapeIDs)
+
+	for _, id := range shapeIDs {
+		e.writeUvarint(uint64(id))
+		encodeShape(s.shapes[id], e)
+		if e.err != nil {
+			return
+		}
+	}
+
+	// Write cells
+	e.writeUvarint(uint64(len(s.cells)))
+	for _, cellID := range s.cells {
+		e.writeUint64(uint64(cellID))
+		cell := s.cellMap[cellID]
+		if cell == nil {
+			e.writeUvarint(0)
+			continue
+		}
+		e.writeUvarint(uint64(len(cell.shapes)))
+		for _, clipped := range cell.shapes {
+			e.writeUvarint(uint64(clipped.shapeID))
+			e.writeBool(clipped.containsCenter)
+			e.writeUvarint(uint64(len(clipped.edges)))
+			for _, edgeID := range clipped.edges {
+				e.writeUvarint(uint64(edgeID))
+			}
+		}
+	}
+}
+
+// Decode decodes the ShapeIndex from r.
+func (s *ShapeIndex) Decode(r io.Reader) error {
+	d := &decoder{r: asByteReader(r)}
+	s.decode(d)
+	return d.err
+}
+
+func (s *ShapeIndex) decode(d *decoder) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+
+	s.Reset()
+
+	version := d.readInt8()
+	if d.err != nil {
+		return
+	}
+	if version != encodingVersion {
+		d.err = fmt.Errorf("can't decode ShapeIndex version %d; my version: %d", version, encodingVersion)
+		return
+	}
+
+	maxEdges := d.readUvarint()
+	if d.err != nil {
+		return
+	}
+	if maxEdges == 0 || maxEdges > 100000 {
+		d.err = fmt.Errorf("invalid maxEdgesPerCell %d", maxEdges)
+		return
+	}
+	s.maxEdgesPerCell = int(maxEdges)
+
+	nextID := d.readUvarint()
+	if d.err != nil {
+		return
+	}
+	if nextID > maxEncodedShapes {
+		d.err = fmt.Errorf("nextID too large (%d; max is %d)", nextID, maxEncodedShapes)
+		return
+	}
+	s.nextID = int32(nextID)
+
+	numShapes := d.readUvarint()
+	if d.err != nil {
+		return
+	}
+	if numShapes > maxEncodedShapes {
+		d.err = fmt.Errorf("too many shapes (%d; max is %d)", numShapes, maxEncodedShapes)
+		return
+	}
+	if uint64(s.nextID) < numShapes {
+		d.err = fmt.Errorf("nextID %d < numShapes %d", s.nextID, numShapes)
+		return
+	}
+
+	for i := 0; i < int(numShapes); i++ {
+		idVal := d.readUvarint()
+		if d.err != nil {
+			return
+		}
+		if idVal >= uint64(s.nextID) {
+			d.err = fmt.Errorf("shapeID %d >= nextID %d", idVal, s.nextID)
+			return
+		}
+		id := int32(idVal)
+		shape, err := decodeShape(d)
+		if err != nil {
+			d.err = err
+			return
+		}
+		if d.err != nil {
+			return
+		}
+		s.shapes[id] = shape
+	}
+
+	numCells := d.readUvarint()
+	if d.err != nil {
+		return
+	}
+	if numCells > maxEncodedCells {
+		d.err = fmt.Errorf("too many cells (%d; max is %d)", numCells, maxEncodedCells)
+		return
+	}
+
+	s.cells = make([]CellID, 0, numCells)
+	for c := 0; c < int(numCells); c++ {
+		cellIDVal := d.readUint64()
+		if d.err != nil {
+			return
+		}
+		cellID := CellID(cellIDVal)
+
+		numClipped := d.readUvarint()
+		if d.err != nil {
+			return
+		}
+		if numClipped > maxClippedShapesPerCell {
+			d.err = fmt.Errorf("too many clipped shapes in cell (%d; max is %d)", numClipped, maxClippedShapesPerCell)
+			return
+		}
+
+		cell := NewShapeIndexCell(int(numClipped))
+		for cs := 0; cs < int(numClipped); cs++ {
+			shapeIDVal := d.readUvarint()
+			containsCenter := d.readBool()
+			numEdges := d.readUvarint()
+			if d.err != nil {
+				return
+			}
+			if numEdges > maxEdgesPerClippedShape {
+				d.err = fmt.Errorf("too many edges in clipped shape (%d; max is %d)", numEdges, maxEdgesPerClippedShape)
+				return
+			}
+
+			shapeID := int32(shapeIDVal)
+			shape, shapeExists := s.shapes[shapeID]
+			if !shapeExists {
+				d.err = fmt.Errorf("cell references non-existent shapeID %d", shapeID)
+				return
+			}
+
+			clipped := &clippedShape{
+				shapeID:        shapeID,
+				containsCenter: containsCenter,
+				edges:          make([]int, numEdges),
+			}
+
+			for e := 0; e < int(numEdges); e++ {
+				edgeIDVal := d.readUvarint()
+				if d.err != nil {
+					return
+				}
+				edgeID := int(edgeIDVal)
+				if edgeID < 0 || edgeID >= shape.NumEdges() {
+					d.err = fmt.Errorf("invalid edgeID %d for shapeID %d (NumEdges=%d)", edgeID, shapeID, shape.NumEdges())
+					return
+				}
+				clipped.edges[e] = edgeID
+			}
+
+			cell.shapes[cs] = clipped
+		}
+
+		s.cellMap[cellID] = cell
+		s.cells = append(s.cells, cellID)
+	}
+
+	atomic.StoreInt32(&s.status, fresh)
+	s.pendingAdditionsPos = s.nextID
+}
+
+func encodeShape(s Shape, e *encoder) {
+	if e.err != nil {
+		return
+	}
+	tag := s.typeTag()
+	if tag == typeTagNone {
+		e.err = fmt.Errorf("unencodable shape type %T", s)
+		return
+	}
+	e.writeUvarint(uint64(tag))
+
+	switch shape := s.(type) {
+	case *Polygon:
+		shape.encode(e)
+	case *Polyline:
+		shape.encode(e)
+	case *PointVector:
+		shape.encode(e)
+	case *LaxPolyline:
+		shape.encode(e)
+	case *LaxPolygon:
+		shape.encode(e)
+	case *Loop:
+		shape.encode(e)
+	case *LaxLoop:
+		shape.encode(e)
+	default:
+		e.err = fmt.Errorf("unsupported shape type %T", s)
+	}
+}
+
+func decodeShape(d *decoder) (Shape, error) {
+	if d.err != nil {
+		return nil, d.err
+	}
+	tagVal := d.readUvarint()
+	if d.err != nil {
+		return nil, d.err
+	}
+	tag := typeTag(tagVal)
+	switch tag {
+	case typeTagPolygon:
+		p := &Polygon{}
+		if err := p.Decode(d.r); err != nil {
+			d.err = err
+			return nil, err
+		}
+		return p, nil
+	case typeTagPolyline:
+		p := &Polyline{}
+		p.decode(*d)
+		return p, d.err
+	case typeTagPointVector:
+		p := &PointVector{}
+		p.decode(d)
+		return p, d.err
+	case typeTagLaxPolyline:
+		p := &LaxPolyline{}
+		p.decode(d)
+		return p, d.err
+	case typeTagLaxPolygon:
+		p := &LaxPolygon{}
+		p.decode(d)
+		return p, d.err
+	case typeTagLoop:
+		p := &Loop{}
+		p.decode(d)
+		return p, d.err
+	case typeTagLaxLoop:
+		p := &LaxLoop{}
+		p.decode(d)
+		return p, d.err
+	default:
+		return nil, fmt.Errorf("unknown shape type tag %d", tag)
+	}
+}
